struct Good {
  int* data;
  Good(int v) { data = new int(v); }
  ~Good() { delete data; }
  Good(const Good& o) { data = new int(*o.data); }  // deep copy
  Good& operator=(const Good& o) {
    if (this != &o) { *data = *o.data; }
    return *this;
  }
};

