class Box {
  double width_;
public:
  Box(double w) : width_(w) {}
  friend double getWidth(const Box& b);  // hàm bạn
};

double getWidth(const Box& b) {
  return b.width_;  // truy cập private trực tiếp
}

class Counter {
public:
  static int total;  // 1 biến cho toàn bộ class
  Counter() { total++; }
  ~Counter() { total--; }

  static int getTotal() { return total; }  // không có `this`
};

int Counter::total = 0;  // phải định nghĩa ngoài class

Counter a, b, c;
std::cout << Counter::total;        // 3
std::cout << Counter::getTotal();   // gọi qua class name

std::vector<int> v = {3, 1, 4, 1, 5, 9};

// sort — O(n log n), sửa tại chỗ
std::sort(v.begin(), v.end());
std::sort(v.begin(), v.end(), std::greater<int>());  // giảm dần

// find — O(n), trả iterator (v.end() nếu không thấy)
auto it = std::find(v.begin(), v.end(), 5);
if (it != v.end()) { /* tìm thấy */ }

// accumulate — fold từ trái sang phải
int sum = std::accumulate(v.begin(), v.end(), 0);  // 23

// transform — apply function, ghi vào output range
std::vector<int> doubled;
std::transform(v.begin(), v.end(), std::back_inserter(doubled),
               [](int x) { return x * 2; });

